import Yagr from '@gravity-ui/yagr';
import type {MinimalValidConfig} from '@gravity-ui/yagr';
export default function MonitoringEngine({data}: {data: {x: number; y: number}[]}) {
  const config = {timeline: data.map((point) => point.x), series: [{}, {data: data.map((point) => point.y), color: 'var(--g-color-line-brand)', width: 1}], axes: [{}, {show: true}], cursor: {show: true}} as MinimalValidConfig;
  return <Yagr id=\"monitoring-series\" config={config} />;
}
EOF
